const ELEMENT_PROP_KEYS = new Set(["theme","word","letter","rest","repeat","stretchAt","stagger","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  word: "Way",
  letter: "",
  rest: "less keyframing.",
  repeat: 5,
  stretchAt: 28,
  stagger: 4,
  accent: "#3B5BFD",
